context.expression:
# ONE entry for every section: the save dialog's Section row picks where
# it lands. Offered when ANY section could take the node - the union of
# what the panel's can_save answers, kept literal so a right-click never
# depends on importing the package.
n = kwargs.get("node", None)
if n is None:
    return False
# Mirrors render/cop_nodes.ITEM_CONTEXTS: every context the Nodes section saves.
KINDS = ("Sop", "Cop", "Lop", "Dop", "Top", "Chop", "Object", "Vop")
try:
    if n.type().category().name() in KINDS:
        return True
except AttributeError:
    pass
for name in ("snippet", "vexpression", "kernelcode", "python", "code"):
    if n.parm(name) is not None:
        return True
try:
    for parm in n.parms():
        t = parm.parmTemplate()
        if t.type() == hou.parmTemplateType.Ramp and t.parmType() == hou.rampParmType.Color:
            return True
except Exception:
    pass
return False

# Context code asks the package and shows nothing: a broken install hides the item, never the menu.
try:
    from amaze.utils import rc_calls
    return rc_calls.convertible(kwargs.get("node", None), "Redshift")
except Exception:
    return False

# Context code asks the package and shows nothing: a broken install hides the item, never the menu.
try:
    from amaze.utils import rc_calls
    return rc_calls.convertible(kwargs.get("node", None), "Karma")
except Exception:
    return False
